"""Three complete original exposed stone domains, Boolean fragments unchanged."""
from pathlib import Path
import numpy as np,trimesh,json,hashlib
R=Path(__file__).resolve().parent;H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();expected='c42bb89b7417421483e6f5c6be0548d027c744e8c5a36d277697f81385700592';assert H(R/'model.stl')==expected
m=trimesh.load(R/'model.stl',force='mesh',process=True);assert len(m.faces)==428
t=m.triangles;n=m.face_normals;e=.0001;a=np.full(len(t),1,np.int32);D={}
for name,ax,p,bounds,count in [('front_stone_frame', 1, -44.5, [[0, -34, 34], [2, 5.5, 103.5]], 10), ('cap_front', 1, -50.5, [[0, -37, 37], [2, 102, 107]], 2), ('left_retaining_exterior', 0, -34, [[1, -45, 71], [2, 5, 103.5]], 51)]:
 hit=abs(t[:,:,ax]-p).max(1)<e
 for k,lo,hi in bounds:hit &= (t[:,:,k].min(1)>=lo-e)&(t[:,:,k].max(1)<=hi+e)
 ids=np.flatnonzero(hit);assert len(ids)==count;D[name]=ids.tolist();a[ids]=0
ad=m.face_adjacency;cop=(n[ad[:,0]]*n[ad[:,1]]).sum(1)>.999999;cs=trimesh.graph.connected_components(ad[cop],nodes=np.arange(len(t)),min_len=1);assert all(len(set(a[c]))==1 for c in cs);assert np.bincount(a).tolist()==[63,365]
pal=[('Observed three exterior pebbled-stone planes nominal gray','#85877E'),('UNVERIFIED main walls entrance windows roofs neutral','#B8BAB5')]
np.savez_compressed(R/'color-mesh.npz',vertices=m.vertices,faces=m.faces,materials=a);(R/'palette.json').write_text(json.dumps(pal,indent=2)+'\n');q={'palette':[{'id':i,'name':name,'hex':col,'faces':int((a==i).sum())}for i,(name,col)in enumerate(pal)],'domain_face_indices':D,'coplanar_components':len(cs),'partial_color_incomplete':True,'fully_colored_exterior':False,'geometry_policy':'428 original triangles unchanged','limits':['Entire glass-backed panel and door opening: reflection/decor not a uniform opaque material', 'Metal lower door and slat faces remain unapproved in this narrow pass', 'Separate protruding horizontal course fronts and their returns', 'Top cap horizontal face/underside/side ends, rear and unseen right cutoff surfaces', 'Ground landing/base and all other original triangles', 'Visitor photos have no independently verifiable capture date. No claim of 2026 current condition. Historical gallery description does not establish present use or date.', 'Only first photographed ground-level entrance and visible descending left retaining wall. No second portal, underground body/corridor, whole covered mound or full museum/gallery interior; unseen right/rear edges are deliberate local cutoffs. Photo57 other entry and photo59 interior are not used.']};(R/'appearance-materials.json').write_text(json.dumps(q,indent=2)+'\n');(R/'COLOR-ASSIGNMENT-QA.json').write_text(json.dumps({'status':'PASS','original_STL_sha256':expected,'triangles':428,'color_mesh_sha256':H(R/'color-mesh.npz')},indent=2));print(q['palette'],'components',len(cs))
